// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Proxy} from "../src/Proxy.sol";

contract InvMutTest is Test {
    Proxy c;
    function setUp() public { c = new Proxy(); }
    function testFuzz_property(address callee, bytes memory data) public {
        vm.assume(callee != address(0));
        vm.assume(callee != address(c));
        vm.assume(data.length <= 10000);

        address alwaysRevert = address(new AlwaysRevert());

        address actor = address(0x1234);
        vm.prank(actor);

        bool forwardSucceeded;
        try c.forward(alwaysRevert, data) {
            forwardSucceeded = true;
        } catch {
            forwardSucceeded = false;
        }

        assertTrue(!forwardSucceeded);
    }
}

contract AlwaysRevert {
    fallback() external { revert(); }
}
